    /**
     * Chunk `index` has been decrypted and written. Strictly in order.
     */
    fun `consumed`(`index`: kotlin.UInt)
    
    /**
     * Chunks decrypted and written so far.
     */
    fun `consumedCount`(): kotlin.UInt
    
    /**
