     * returned (or `UseApiNow` for a network error).
     */
    fun `windowFailed`(`outcome`: DirectOutcomeDto, `nowMs`: kotlin.Long)
    
    /**
     * A 2xx window response whose body could not be decoded at all.
     */
    fun `windowMalformed`()
    
    companion object
}

